/// <summary>
/// Constructs a new METInventTransferOrderPostingInfoBusinessEvent business event.
/// </summary>
/// <param name = "_journalTable">The <c>InventJournalTable</c> record.</param>
/// <returns>A new <c>METInventTransferOrderPostingInfoBusinessEvent</c> business event.</returns>
public static METInventTransferOrderPostingInfoBusinessEvent newFromInventTransferOrder(InventJournalTable _journalTable)
{
    METInventTransferOrderPostingInfoBusinessEvent event = new METInventTransferOrderPostingInfoBusinessEvent();
    event.parmInventJournalTable(_journalTable);
    return event;
}

/// <summary>
/// Gets and sets <c>InventJournalTable</c>.
/// </summary>
/// <param name = "_inventJournalTable"><c>InventJournalTable</c>.
/// </param>
/// <returns>
/// <c>InventJournalTable</c>.
/// </returns> parmInventjournalTable is a table
private InventJournalTable parmInventJournalTable(InventJournalTable _inventJournalTable = journalTable)
{
    journalTable = _inventJournalTable;
    return journalTable;
}

/// <summary>
/// Constructs a new METInventTransferOrderPostingInfoContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METInventTransferOrderPostingInfoContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
protected BusinessEventsContract buildContract()
{
    return METInventTransferOrderPostingInfoContract::newFromInventTransferOrder(journalTable);
}
